def compute_Last_Digit(a, b):
    if a > b:
        return 0
    if a == 0 or a == 1:
        return 1 % 10  # 0! = 1, 1! = 1

    # We need to compute (b! / a!) % 10
    # This is equivalent to computing the product of numbers from (a+1) to b modulo 10
    result = 1
    for i in range(a + 1, b + 1):
        result = (result * i) % 10
        if result == 0:
            break
    return result
