def comb_sort(arr):
    if len(arr) <= 1:
        return arr

    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        sorted = True
        gap = int(gap / shrink_factor)

        if gap > 0:
            for i in range(len(arr) - gap):
                if arr[i] > arr[i + gap]:
                    arr[i], arr[i + gap] = arr[i + gap], arr[i]
                    sorted = False
        else:
            gap = 1

    return arr
