def pancake_sort(arr):
    def flip(arr, k):
        arr[:k+1] = arr[:k+1][::-1]
        return arr

    n = len(arr)
    for current in range(n, 1, -1):
        # Find index of the maximum element in arr[0:current]
        max_idx = 0
        for i in range(1, current):
            if arr[i] > arr[max_idx]:
                max_idx = i

        # Flip max element to the front
        if max_idx != current - 1:
            if max_idx != 0:
                flip(arr, max_idx)
            flip(arr, current - 1)

    return arr
```

