def find_longest_repeating_subseq(s: str) -> int:
    n = len(s)
    # dp[i][j] will store the length of the longest repeating subsequence 
    # between s[0:i] and s[0:j] such that characters at same positions are different.
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and s[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]
```

