def get_Min_Squares(n: int) -> int:
    """
    Returns the minimum number of perfect squares that sum up to n.
    Uses dynamic programming.
    """
    if n <= 0:
        return 0

    dp = [0] + [float('inf')] * n

    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if j * j > i:
                break
            dp[i] = min(dp[i], dp[i - j * j] + 1)

    return dp[n]
