def count_bidirectional(pairs):
    from collections import defaultdict
    forward = defaultdict(int)
    backward = defaultdict(int)

    for a, b in pairs:
        forward[(a, b)] += 1
        backward[(b, a)] += 1

    count = 0
    for key in forward:
        if forward[key] > 0 and backward[key] > 0:
            count += forward[key] * backward[key]

    return str(count)
