def cal_sum(n):
    if n < 0:
        return 0

    # Perrin sequence: P(0)=0, P(1)=1, P(2)=1, P(n) = P(n-2) + P(n-3) for n > 2
    if n == 0:
        return 0
    if n == 1 or n == 2:
        return 1

    p = [0, 1, 1]
    for i in range(3, n + 1):
        p.append(p[i-2] + p[i-3])

    return sum(p)
