def heap_queue_smallest(nums, k):
    if k <= 0:
        return []
    if k >= len(nums):
        return sorted(nums)

    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, num)
        else:
            if num < heap[0]:
                heapq.heapreplace(heap, num)

    return sorted(heap)
